import test,{before,after} from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import {id,sessionDates,today} from '../public/modules/core.mjs';
const dir=fs.mkdtempSync(path.join(os.tmpdir(),'red-academy-api-'));
process.env.DATABASE_MODE='sqlite';process.env.DATABASE_PATH=path.join(dir,'api.db');process.env.SEED_SAMPLE_DATA='false';
process.env.BOOTSTRAP_ADMIN_EMAIL='admin@example.test';process.env.BOOTSTRAP_ADMIN_PASSWORD='API-Test-Password-123!';
process.env.APP_URL='http://localhost:3000';delete process.env.APP_ENV;delete process.env.OPENAI_API_KEY;delete process.env.OPENAI_MODEL;
const {handleApi,repository}=await import('../server/service.mjs');
let adminCookie='',viewerCookie='',instructorCookie='',company,batch,trainee;
async function request(route,{method='GET',body,cookie='',origin=process.env.APP_URL,custom=true,raw}={}){
 const headers=new Headers();if(cookie)headers.set('cookie',cookie);if(method!=='GET'){headers.set('content-type','application/json');if(origin)headers.set('origin',origin);if(custom)headers.set('x-red-request','1');}
 const response=await handleApi(new Request(process.env.APP_URL+'/api/'+route,{method,headers,...(method!=='GET'?{body:raw??JSON.stringify(body||{})}:{})}));
 const data=response.headers.get('content-type')?.includes('application/json')?await response.json():null;
 return {response,data,status:response.status,cookie:response.headers.getSetCookie().map(x=>x.split(';')[0]).join('; ')};
}
before(async()=>{const repo=await repository();await repo.setup({token:repo.setupToken,email:'admin@example.test',full_name:'Test Administrator',password:process.env.BOOTSTRAP_ADMIN_PASSWORD});const login=await request('auth/login',{method:'POST',body:{email:'admin@example.test',password:process.env.BOOTSTRAP_ADMIN_PASSWORD}});assert.equal(login.status,200);adminCookie=login.cookie;assert.equal((await request('state',{cookie:adminCookie})).data.companies.length,0);company=(await request('mutate',{method:'POST',cookie:adminCookie,body:{table:'companies',action:'create',data:{name:'API Company'}}})).data.records[0];
 for(const role of ['viewer','instructor']){
  const invite=await request('invitations',{method:'POST',cookie:adminCookie,body:{email:role+'@example.test',full_name:role,role}});assert.equal(invite.status,201);assert.equal((await request('auth/accept-invitation',{method:'POST',body:{token:invite.data.token,password:'API-Test-Password-123!',role:'admin'}})).status,201);
  const list=await request('users',{cookie:adminCookie});const user=list.data.find(u=>u.email===role+'@example.test');
  assert.equal((await request('users',{method:'PATCH',cookie:adminCookie,body:{id:user.id,role,active:true}})).status,200);
  const login=await request('auth/login',{method:'POST',body:{email:user.email,password:'API-Test-Password-123!'}});
  if(role==='viewer')viewerCookie=login.cookie;else instructorCookie=login.cookie;
 }
 const b=await request('mutate',{method:'POST',cookie:adminCookie,body:{table:'batches',action:'create',data:{batch_name:'API Batch',status:'Active',start_date:'2026-09-06',end_date:'2026-09-19',session_dates:sessionDates('2026-09-06'),capacity:20,description:''}}});assert.equal(b.status,200);batch=b.data.records[0];
 const t=await request('mutate',{method:'POST',cookie:adminCookie,body:{table:'trainees',action:'create',data:{trainee_name:'API Trainee',company_id:company.id,batch_id:batch.id,email:'',phone:'',job_title:'',notes:''}}});assert.equal(t.status,200);assert.equal(t.data.records.length,2);trainee=t.data.records[0];assert.equal(trainee.enrollment_status,'Active');
});
after(async()=>{(await repository()).close();fs.rmSync(dir,{recursive:true,force:true});});
test('Unauthenticated session is public; private data returns 401',async()=>{assert.equal((await request('session')).data.user,null);assert.equal((await request('state')).status,401);});
test('Session cookie is opaque, HttpOnly and SameSite=Lax',async()=>{const r=await request('auth/login',{method:'POST',body:{email:'admin@example.test',password:process.env.BOOTSTRAP_ADMIN_PASSWORD}});const cookie=r.response.headers.getSetCookie()[0];assert.match(cookie,/HttpOnly/);assert.match(cookie,/SameSite=Lax/);assert.ok(!cookie.includes('admin@example'));});
test('Wrong Origin and missing custom header are blocked',async()=>{assert.equal((await request('mutate',{method:'POST',cookie:adminCookie,origin:'https://evil.example',body:{}})).status,403);assert.equal((await request('auth/login',{method:'POST',custom:false,body:{}})).status,403);});
test('Malformed and non-object JSON bodies return 400, not a server crash',async()=>{for(const raw of ['{bad','null','[]','4'])assert.equal((await request('auth/login',{method:'POST',raw})).status,400);});
test('Public registration is disabled and cannot create accounts',async()=>{const email='pending@example.test';assert.equal((await request('auth/register',{method:'POST',body:{email,password:'API-Test-Password-123!',full_name:'Pending',role:'admin',active:true}})).status,403);assert.equal((await request('auth/login',{method:'POST',body:{email,password:'API-Test-Password-123!'}})).status,401);});
test('Viewer reads but cannot write or administer accounts',async()=>{assert.equal((await request('state',{cookie:viewerCookie})).status,200);assert.equal((await request('mutate',{method:'POST',cookie:viewerCookie,body:{table:'companies',action:'create',data:{name:'Forbidden'}}})).status,403);assert.equal((await request('users',{cookie:viewerCookie})).status,403);assert.equal((await request('users',{method:'PATCH',cookie:viewerCookie,body:{id:trainee.id,role:'admin',active:true}})).status,403);});
test('Live facilitator answer keys are private to writable staff',async()=>{assert.equal((await request('activities/facilitator-deck')).status,401);assert.equal((await request('activities/facilitator-deck',{cookie:viewerCookie})).status,403);const trainer=await request('activities/facilitator-deck',{cookie:instructorCookie});assert.equal(trainer.status,200);assert.ok(trainer.data.activities[0].questions[0].explanation);assert.ok(Number.isInteger(trainer.data.activities[0].questions[0].answer));const publicLibrary=await request('activities/library',{cookie:viewerCookie});assert.equal(publicLibrary.status,200);assert.ok(publicLibrary.data.activities.every(activity=>!('questions'in activity)&&!('answer'in activity)));});
test('Admins can correct a staff display name without changing access or ending its session',async()=>{const member=(await request('users',{cookie:adminCookie})).data.find(user=>user.email==='viewer@example.test');assert.ok(member);assert.equal((await request('users/profile',{method:'PATCH',cookie:viewerCookie,body:{id:member.id,full_name:'Viewer Unauthorized'}})).status,403);for(const full_name of ['', 'x'.repeat(161), 'Invalid\nName'])assert.equal((await request('users/profile',{method:'PATCH',cookie:adminCookie,body:{id:member.id,full_name}})).status,400);const changed=await request('users/profile',{method:'PATCH',cookie:adminCookie,body:{id:member.id,full_name:'Viewer Updated'}});assert.equal(changed.status,200);const saved=(await request('users',{cookie:adminCookie})).data.find(user=>user.id===member.id);assert.equal(saved.full_name,'Viewer Updated');assert.equal(saved.role,'viewer');assert.equal(saved.active,true);assert.equal((await request('session',{cookie:viewerCookie})).data.user.full_name,'Viewer Updated');assert.ok((await request('state',{cookie:adminCookie})).data.audit_log.some(row=>row.action==='display-name'&&row.entity_id===member.id));});
test('Batch archive is admin-only, audited, reversible, and leaves linked records intact',async()=>{
 assert.equal((await request('batches/archive',{method:'POST',body:{id:batch.id,expectedVersion:batch.version,archived:true}})).status,401);
 assert.equal((await request('batches/archive',{method:'POST',cookie:viewerCookie,body:{id:batch.id,expectedVersion:batch.version,archived:true}})).status,403);
 assert.equal((await request('batches/archive',{method:'POST',cookie:instructorCookie,body:{id:batch.id,expectedVersion:batch.version,archived:true}})).status,403);
 const archived=await request('batches/archive',{method:'POST',cookie:adminCookie,body:{id:batch.id,expectedVersion:batch.version,archived:true}});assert.equal(archived.status,200);assert.ok(archived.data.record.archived_at);assert.equal(archived.data.record.archived_by,'admin@example.test');
 const state=await request('state',{cookie:adminCookie});assert.ok(state.data.batches.some(row=>row.id===batch.id&&row.archived_at));assert.ok(state.data.trainees.some(row=>row.id===trainee.id));
 assert.equal((await request('batches/archive',{method:'POST',cookie:adminCookie,body:{id:batch.id,expectedVersion:batch.version,archived:false}})).status,409);
 const restored=await request('batches/archive',{method:'POST',cookie:adminCookie,body:{id:batch.id,expectedVersion:archived.data.record.version,archived:false}});assert.equal(restored.status,200);assert.equal(restored.data.record.archived_at,null);assert.equal(restored.data.record.archived_by,null);
 assert.equal((await request('batches/archive',{method:'POST',cookie:adminCookie,body:{id:'not-a-uuid',expectedVersion:1,archived:true}})).status,400);
});
test('Instructor can create records but cannot delete company records',async()=>{const r=await request('mutate',{method:'POST',cookie:instructorCookie,body:{table:'companies',action:'create',data:{name:'Instructor Company'}}});assert.equal(r.status,200);assert.equal((await request('mutate',{method:'POST',cookie:instructorCookie,body:{table:'companies',action:'delete',id:r.data.records[0].id,expectedVersion:1}})).status,403);});
