 const batchResponse=await request('mutate',{method:'POST',cookie:adminCookie,body:{table:'batches',action:'create',data:{batch_name:'Instructor Delete Batch',status:'Planning',start_date:'2026-10-01',end_date:'2026-10-14',session_dates:sessionDates('2026-10-01'),capacity:10,description:''}}});assert.equal(batchResponse.status,200,JSON.stringify(batchResponse.data));const newBatch=batchResponse.data.records[0];
 const traineeResponse=await request('mutate',{method:'POST',cookie:adminCookie,body:{table:'trainees',action:'create',data:{trainee_name:'Instructor Delete Trainee',company_id:company.id,batch_id:newBatch.id,email:'',phone:'',job_title:'',notes:''}}});assert.equal(traineeResponse.status,200,JSON.stringify(traineeResponse.data));const newTrainee=traineeResponse.data.records[0];
 assert.equal((await request('mutate',{method:'POST',cookie:instructorCookie,body:{table:'trainees',action:'delete',id:newTrainee.id,expectedVersion:newTrainee.version}})).status,200);
