test('Activity assignments use the authenticated Academy roster and are shared immediately',async()=>{
 assert.equal((await request('activities')).status,401);
 const created=await request('activities/assign',{method:'POST',cookie:instructorCookie,body:{batch_id:batch.id,activity_id:'rapidfire',instructions:'Focus on concise discovery questions.',due_date:'2026-09-30',trainee_ids:[trainee.id]}});
 assert.equal(created.status,201,JSON.stringify(created.data));
 assert.equal(created.data.record.title,'Rapid Fire');
 assert.equal(created.data.record.created_by,'instructor@example.test');
 const adminView=await request('activities',{cookie:adminCookie});
 const assignment=adminView.data.assignments.find(row=>row.id===created.data.record.id);
 assert.equal(assignment.batch_name,'API Batch');assert.equal(assignment.participants[0].trainee_id,trainee.id);assert.equal(assignment.participants[0].trainee_name,'API Trainee');
 assert.equal((await request('activities/assign',{method:'POST',cookie:viewerCookie,body:{batch_id:batch.id,activity_id:'rapidfire',trainee_ids:[trainee.id]}})).status,403);
 const update=await request('activities/participant',{method:'PATCH',cookie:instructorCookie,body:{assignment_id:assignment.id,trainee_id:trainee.id,expected_version:1,status:'Completed',score:87.5,trainer_feedback:'Strong discovery; add one follow-up question.'}});
 assert.equal(update.status,200,JSON.stringify(update.data));assert.equal(update.data.record.score,87.5);assert.ok(update.data.record.completed_at);
 const latest=(await request('activities',{cookie:adminCookie})).data.assignments.find(row=>row.id===assignment.id);
 assert.equal(latest.participants[0].status,'Completed');assert.equal(latest.participants[0].trainer_feedback,'Strong discovery; add one follow-up question.');
 assert.equal((await request('activities/participant',{method:'PATCH',cookie:instructorCookie,body:{assignment_id:assignment.id,trainee_id:trainee.id,expected_version:1,status:'In Progress',score:null,trainer_feedback:''}})).status,409);
 const closed=await request('activities/close',{method:'POST',cookie:instructorCookie,body:{id:assignment.id,expected_version:1,status:'Closed'}});
 assert.equal(closed.status,200);assert.equal(closed.data.record.status,'Closed');
 assert.equal((await request('activities/participant',{method:'PATCH',cookie:instructorCookie,body:{assignment_id:assignment.id,trainee_id:trainee.id,expected_version:2,status:'In Progress',score:null,trainer_feedback:''}})).status,409);
});
