test('Live quiz confidence is private before reveal and becomes only an anonymous cohort signal',async()=>{
 const before=(await request('state',{cookie:adminCookie})).data;
 const activity=(await request('activities/facilitator-deck',{cookie:instructorCookie})).data.activities.find(item=>item.id==='quiz-discovery');
 const created=await request('activities/live/create',{method:'POST',cookie:adminCookie,body:{activity_id:activity.id,teams:['North Stars','Bright Sparks'],timer_duration:0}});
 assert.equal(created.status,201,JSON.stringify(created.data));const roomId=created.data.room_id,code=created.data.join_code,correct=activity.questions[0].answer,wrong=(correct+1)%activity.questions[0].options.length,seats=[];
 for(let index=0;index<7;index++){
  const joined=await request('activities/live/join',{method:'POST',body:{code,nickname:`Reflect ${index}`,team_no:index%2+1}});
  assert.equal(joined.status,200,JSON.stringify(joined.data));seats.push(joined.data.seat_token);
 }
 assert.equal((await request('activities/live/answer',{method:'POST',body:{seat_token:seats[0],choice:correct,confidence:'certain'}})).status,400);
 const correctPattern=[false,true,false,true,true,true,true];
 for(let index=0;index<seats.length;index++){
  const confidence=index<3?'confident':index<6?'tentative':undefined;
  const body={seat_token:seats[index],choice:correctPattern[index]?correct:wrong,...(confidence?{confidence}:{})};
  const submitted=await request('activities/live/answer',{method:'POST',body});
  assert.equal(submitted.status,200,JSON.stringify(submitted.data));
  assert.equal(submitted.data.player.confidence,confidence??null);
  assert.equal('confidence_summary'in submitted.data,false);
  if(index===0){
   const ownState=await request('activities/live/state',{method:'POST',body:{seat_token:seats[0]}});
   assert.equal(ownState.data.player.confidence,'confident');
   assert.equal('confidence_summary'in ownState.data,false);
  }
 }
 const hidden=await request('activities/live/host?room_id='+roomId,{cookie:adminCookie});
 assert.equal(hidden.status,200);assert.equal(hidden.data.confidence_summary,null);assert.deepEqual(hidden.data.responses,[]);
 const revealed=await request('activities/live/reveal',{method:'POST',cookie:adminCookie,body:{room_id:roomId}});
 assert.equal(revealed.status,200);
 assert.deepEqual(revealed.data.confidence_summary,{count:6,confident:{count:3,accuracy:33},tentative:{count:3,accuracy:100}});
 assert.ok(revealed.data.responses.every(response=>!('confidence'in response)));
 assert.equal(JSON.stringify(revealed.data.responses).includes('tentative'),false);
 assert.equal((await request('activities/live/close',{method:'POST',cookie:adminCookie,body:{room_id:roomId}})).status,200);
 const after=(await request('state',{cookie:adminCookie})).data;
 for(const key of ['batches','trainees','assessments','daily_attendance'])assert.deepEqual(after[key],before[key],`live confidence changed ${key}`);
});
