test('API state excludes password hashes and session tokens',async()=>{const r=await request('state',{cookie:adminCookie});assert.ok(!JSON.stringify(r.data).includes('password_hash'));assert.ok(!('users'in r.data));assert.ok(!('sessions'in r.data));assert.equal(r.response.headers.get('cache-control'),'no-store');});
test('Score validation rejects tampered out-of-range requests',async()=>{const data={trainee_id:trainee.id,batch_id:batch.id,assessment_title:'Final',mapping:99,product_knowledge:5,presentability:5,soft_skills:5,assessment_outcome:'Aced',instructor_comment:'',report:'',report_kind:'template'};assert.equal((await request('mutate',{method:'POST',cookie:adminCookie,body:{table:'assessments',action:'create',data}})).status,400);});
test('Bulk attendance is all-or-nothing on duplicate daily entries',async()=>{const data={trainee_id:trainee.id,batch_id:batch.id,date:batch.start_date,arrival_time:null,departure_time:null,status:'Absent',is_late:false};const r=await request('mutate',{method:'POST',cookie:adminCookie,body:{table:'daily_attendance',records:[{action:'create',data},{action:'create',data}]}});assert.equal(r.status,409);const state=(await request('state',{cookie:adminCookie})).data;assert.equal(state.daily_attendance.filter(r=>r.trainee_id===trainee.id).length,0);});
test('Assessment day saves with present attendance and trainee can be marked stopped',async()=>{let response=await request('mutate',{method:'POST',cookie:adminCookie,body:{table:'daily_attendance',action:'create',data:{trainee_id:trainee.id,batch_id:batch.id,date:batch.session_dates[1],arrival_time:null,departure_time:null,status:'Present',assessment_day:true,is_late:false}}});assert.equal(response.status,200);assert.equal(response.data.records[0].assessment_day,true);assert.equal(response.data.records[0].status,'Present');let updated=await request('mutate',{method:'POST',cookie:adminCookie,body:{table:'trainees',action:'update',id:trainee.id,expectedVersion:1,data:{...trainee,enrollment_status:'Stopped Attending'}}});assert.equal(updated.status,200);assert.equal(updated.data.records[0].enrollment_status,'Stopped Attending');updated=await request('mutate',{method:'POST',cookie:adminCookie,body:{table:'trainees',action:'update',id:trainee.id,expectedVersion:2,data:{...updated.data.records[0],enrollment_status:'Active'}}});assert.equal(updated.status,200);});
test('Stale expectedVersion returns conflict without overwriting',async()=>{const body={table:'companies',action:'update',id:company.id,expectedVersion:1,data:{name:'API Renamed Company'}};assert.equal((await request('mutate',{method:'POST',cookie:adminCookie,body})).status,200);assert.equal((await request('mutate',{method:'POST',cookie:adminCookie,body})).status,409);});
test('AI without provider configuration returns 503, not a fabricated AI report',async()=>assert.equal((await request('ai',{method:'POST',cookie:adminCookie,body:{traineeId:trainee.id,kind:'attendance',consent:true}})).status,503));
test('Unknown tables and endpoints are rejected',async()=>{assert.equal((await request('mutate',{method:'POST',cookie:adminCookie,body:{table:'users',action:'create',data:{role:'admin'}}})).status,400);assert.equal((await request('no-such-route',{cookie:adminCookie})).status,404);});
test('Live event stream emits a change notification after a successful mutation',async()=>{const controller=new AbortController();const response=await handleApi(new Request(process.env.APP_URL+'/api/events',{headers:{cookie:adminCookie},signal:controller.signal}));assert.equal(response.status,200);assert.match(response.headers.get('content-type'),/text\/event-stream/);const reader=response.body.getReader();assert.match(new TextDecoder().decode((await reader.read()).value),/connected/);await request('mutate',{method:'POST',cookie:adminCookie,body:{table:'companies',action:'create',data:{name:'SSE Company'}}});const next=await reader.read();assert.match(new TextDecoder().decode(next.value),/refresh/);controller.abort();await reader.cancel();});
test('Logout invalidates the session and expires its cookie',async()=>{const login=await request('auth/login',{method:'POST',body:{email:'instructor@example.test',password:'API-Test-Password-123!'}});const r=await request('auth/logout',{method:'POST',cookie:login.cookie});assert.match(r.response.headers.getSetCookie()[0],/Max-Age=0/);assert.equal((await request('state',{cookie:login.cookie})).status,401);});
